import assert from 'node:assert/strict';import {chromium} from 'playwright-core';
let browser;try{browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-webgl','--ignore-gpu-blocklist','--use-angle=metal']});const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:5277/qa/exo-avatar-exact-body-20261102.html',{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.__exactBodyResult!==null,null,{timeout:60000});const result=await page.evaluate(()=>window.__exactBodyResult);console.log('EXO_EXACT_SKIN_COLLIDER',JSON.stringify({result,errors},null,2));assert.ok(!result.error,result.error);assert.equal(result.matched5mm,true);assert.ok(result.bodyVertices>=13000);assert.ok(result.skinnedMeshes>=1);assert.deepEqual(errors,[])}finally{await browser?.close()}
